NativeSignal configure_framed_control_procedure(
    VM& vm, Thread& thread,
    VM::FramedControlProcedureKind kind) {
    std::array<uint32_t, 12> operands{};
    for (std::size_t index = operands.size(); index != 0; --index) {
        operands[index - 1] = thread.stack.pop();
    }
    const uint32_t status = vm.configure_framed_control_procedure(
        kind, operands, thread.base);
    if (status != 0) {
        std::ostringstream message;
        message << "Grp0 framed control procedure failed with status 0x"
                << std::hex << std::uppercase << status;
        throw std::runtime_error(message.str());
    }
    if (kind == VM::FramedControlProcedureKind::Framed &&
        !vm.install_framed_control_display_procedure(thread,operands))
        throw std::runtime_error("Grp0:28 failed to install original display controller");
    if (kind == VM::FramedControlProcedureKind::Recorded &&
        !vm.install_recorded_linear_display_procedure(thread,operands))
        throw std::runtime_error("Grp0:29 failed to install recorded display controller");
    if (debug_trace(DebugTrace::Display)) {
        std::cout << "FRAMED_CONTROL_ARGS kind=" << static_cast<unsigned>(kind);
        for (uint32_t value:operands) std::cout << ',' << value;
        std::cout << '\n';
    }
    return NativeSignal::Yield;
}
